import Foundation
import CommonCrypto

// Secure message framing protocol parser
// Frame format: [version:1][flags:1][headerLen:2][payloadLen:4][header][payload][mac:32]

struct FrameConfig {
    let maxHeaderSize: Int = 8192
    let maxPayloadSize: Int = 1_048_576  // 1MB
    let hmacKey: Data

    init(key: Data) {
        self.hmacKey = key
    }
}

enum FrameError: Error {
    case invalidVersion
    case frameTooShort
    case headerTooLarge
    case payloadTooLarge
    case integrityFailure
    case invalidEncoding
}

struct ParsedFrame {
    let version: UInt8
    let flags: UInt8
    let header: Data
    let payload: Data
}

class SecureFrameParser {
    private let config: FrameConfig
    private var frameCount: UInt64 = 0
    private var lastFrameTime: Date = Date()

    init(config: FrameConfig) {
        self.config = config
    }

    // Constant-time HMAC comparison
    private func verifyHMAC(data: Data, expectedMAC: Data) -> Bool {
        var computedMAC = Data(count: Int(CC_SHA256_DIGEST_LENGTH))
        config.hmacKey.withUnsafeBytes { keyPtr in
            data.withUnsafeBytes { dataPtr in
                computedMAC.withUnsafeMutableBytes { macPtr in
                    CCHmac(
                        CCHmacAlgorithm(kCCHmacAlgSHA256),
                        keyPtr.baseAddress!, config.hmacKey.count,
                        dataPtr.baseAddress!, data.count,
                        macPtr.baseAddress!
                    )
                }
            }
        }
        // Constant-time comparison
        guard computedMAC.count == expectedMAC.count else { return false }
        var result: UInt8 = 0
        for i in 0..<computedMAC.count {
            result |= computedMAC[i] ^ expectedMAC[i]
        }
        return result == 0
    }

    // Extract length field with network byte order conversion
    private func extractPayloadLength(from data: Data, at offset: Int) -> Int32 {
        let b0 = Int32(data[offset]) << 24
        let b1 = Int32(data[offset + 1]) << 16
        let b2 = Int32(data[offset + 2]) << 8
        let b3 = Int32(data[offset + 3])
        return b0 | b1 | b2 | b3
    }

    private func extractHeaderLength(from data: Data, at offset: Int) -> UInt16 {
        let b0 = UInt16(data[offset]) << 8
        let b1 = UInt16(data[offset + 1])
        return b0 | b1
    }

    // Validate frame structure before parsing
    private func validateFrameStructure(data: Data) throws -> (headerLen: Int, payloadLen: Int) {
        // Minimum frame: version(1) + flags(1) + headerLen(2) + payloadLen(4) + mac(32) = 40
        guard data.count >= 40 else {
            throw FrameError.frameTooShort
        }

        let version = data[0]
        guard version == 1 || version == 2 else {
            throw FrameError.invalidVersion
        }

        let headerLen = Int(extractHeaderLength(from: data, at: 2))
        let payloadLen32 = extractPayloadLength(from: data, at: 4)

        // Bounds check on header
        guard headerLen <= config.maxHeaderSize else {
            throw FrameError.headerTooLarge
        }

        // Bounds check on payload - compare as Int32 to catch "negative" lengths
        guard payloadLen32 <= Int32(config.maxPayloadSize) else {
            throw FrameError.payloadTooLarge
        }

        let payloadLen = Int(payloadLen32)

        // Verify total frame size is consistent
        let expectedSize = 8 + headerLen + payloadLen + 32
        guard data.count >= expectedSize else {
            throw FrameError.frameTooShort
        }

        return (headerLen, payloadLen)
    }

    // Parse and authenticate a frame
    func parseFrame(data: Data) throws -> ParsedFrame {
        let (headerLen, payloadLen) = try validateFrameStructure(data: data)

        // Extract MAC (last 32 bytes of expected frame)
        let frameEnd = 8 + headerLen + payloadLen + 32
        let macStart = frameEnd - 32
        let mac = data.subdata(in: macStart..<frameEnd)

        // Verify HMAC over everything except the MAC itself
        let authenticatedData = data.subdata(in: 0..<macStart)
        guard verifyHMAC(data: authenticatedData, expectedMAC: mac) else {
            throw FrameError.integrityFailure
        }

        // Extract fields
        let version = data[0]
        let flags = data[1]
        let header = data.subdata(in: 8..<(8 + headerLen))
        let payload = data.subdata(in: (8 + headerLen)..<(8 + headerLen + payloadLen))

        frameCount += 1
        lastFrameTime = Date()

        return ParsedFrame(version: version, flags: flags, header: header, payload: payload)
    }

    // Process multiple frames from a stream buffer
    func processBuffer(buffer: Data, maxFrames: Int = 100) throws -> [ParsedFrame] {
        var frames: [ParsedFrame] = []
        var offset = 0

        while offset < buffer.count && frames.count < maxFrames {
            // Read frame length prefix (4 bytes, big-endian unsigned)
            guard offset + 4 <= buffer.count else { break }
            let frameLenBytes = buffer.subdata(in: offset..<(offset + 4))
            let frameLen = Int(frameLenBytes[0]) << 24 | Int(frameLenBytes[1]) << 16 |
                          Int(frameLenBytes[2]) << 8 | Int(frameLenBytes[3])

            guard frameLen > 0 && frameLen <= buffer.count - offset - 4 else { break }

            let frameData = buffer.subdata(in: (offset + 4)..<(offset + 4 + frameLen))
            let frame = try parseFrame(data: frameData)
            frames.append(frame)

            offset += 4 + frameLen
        }

        return frames
    }
}
